INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朝廷敕令卢台乱兵在营家属全门处斩", "start_year": 927, "end_year": 927, "time_original": "927年四月庚寅", "dynasty": "五代十国", "description": "朝廷敕令卢台乱兵在营家属全门处斩。", "phases": [], "location_name": "后唐朝廷至邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ea23e456-8e7d-5e76-af81-776320f4db1b"}, {"title": "敕到邺都，九指挥闭门，将三千五百家万余人驱至石灰窑全部斩杀", "start_year": 927, "end_year": 927, "time_original": "927年四月庚寅敕至邺都之后，执行确日未另记", "dynasty": "五代十国", "description": "敕到邺都，九指挥闭门，将三千五百家万余人驱至石灰窑全部斩杀。", "phases": [], "location_name": "邺都石灰窑", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8bd0f180-bace-5fb7-af23-7da419835a54"}, {"title": "朝廷加房知温兼侍中，史书称虽知其首乱仍欲安定反侧者", "start_year": 927, "end_year": 927, "time_original": "927年四月癸巳", "dynasty": "五代十国", "description": "朝廷加房知温兼侍中，史书称虽知其首乱仍欲安定反侧者。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb3eb728-f309-5e35-950e-76dc4485e89a"}, {"title": "安审通加检校太傅，旧书记以卢台之功奖赏", "start_year": 927, "end_year": 927, "time_original": "927年四月癸巳", "dynasty": "五代十国", "description": "安审通加检校太傅，旧书记以卢台之功奖赏。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "407d0b4e-a64b-5e24-9911-0aea861114f0"}, {"title": "孟知祥遣武漳到晋阳迎妻琼华长公主及子仁赞", "start_year": null, "end_year": null, "time_original": "927年四月入成都前的先是追叙，派遣日未载", "dynasty": "五代十国", "description": "孟知祥遣武漳到晋阳迎妻琼华长公主及子仁赞。", "phases": [], "location_name": "晋阳至蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "910ba847-87ed-5593-a129-4ffb614887a3"}, {"title": "李继曮闻孟知祥杀李严，家属到凤翔时将其留住并奏报", "start_year": null, "end_year": null, "time_original": "李严被杀之后至927年四月家属到成都前，确日未载", "dynasty": "五代十国", "description": "李继曮闻孟知祥杀李严，家属到凤翔时将其留住并奏报。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7eb80c01-e82a-55f0-a659-604dcb10c722"}, {"title": "李嗣源允许孟知祥家属归蜀", "start_year": null, "end_year": null, "time_original": "凤翔奏报之后、927年四月丙申到成都前，许归日未载", "dynasty": "五代十国", "description": "李嗣源允许孟知祥家属归蜀。", "phases": [], "location_name": "后唐朝廷至凤翔、蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "afa1a601-3e71-5fa5-b30e-16a707f675c1"}, {"title": "琼华长公主及孟仁赞一行到成都", "start_year": 927, "end_year": 927, "time_original": "927年四月丙申", "dynasty": "五代十国", "description": "琼华长公主及孟仁赞一行到成都。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3aa7e30b-edf0-56d3-92b7-73cba8275380"}, {"title": "孟知祥因与盐铁判官赵季良有旧，奏留为副使", "start_year": null, "end_year": null, "time_original": "927年四月丁酉朝命之前奏请，确日未载", "dynasty": "五代十国", "description": "孟知祥因与盐铁判官赵季良有旧，奏留为副使。", "phases": [], "location_name": "成都奏后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "18c42891-d346-5dd8-bf41-fbfe1b361b39"}, {"title": "赵季良获任西川节度副使", "start_yea